"""Turn the three plain-text files into records.

Every rule violation raises :class:`ParseError`, a ``ValueError`` that carries
the 1-based line number (blank and comment lines count) in ``.line``.
"""

import datetime
import re
from dataclasses import dataclass, field
from decimal import Decimal
from typing import Dict, Iterator, List, Optional, Tuple

#: Whitespace means ASCII space and tab only.
WS = " \t"

#: Longest run of digits (leading zeros ignored) accepted in a whole number.
#: Keeps ``int()`` away from interpreter digit limits and from absurd input.
MAX_DIGITS = 1000

TAX_RATES = {"standard": 20, "reduced": 5, "zero": 0}

_SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}", re.ASCII)
_PRICE_RE = re.compile(r"([0-9]+)(?:\.([0-9]{1,2}))?", re.ASCII)
_UINT_RE = re.compile(r"[0-9]+", re.ASCII)
_SINT_RE = re.compile(r"([+-]?)([0-9]+)", re.ASCII)
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", re.ASCII)
_ORDER_RE = re.compile(r"[Ss][Oo]-[0-9]+", re.ASCII)
_LINE_RE = re.compile(r"([A-Za-z]{2,4}-[0-9]{3})\*([0-9]+)", re.ASCII)
_MOVE_RE = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.DOTALL)


class ParseError(ValueError):
    """A mistake in one line of a data file. ``.line`` is the 1-based line."""

    def __init__(self, line: int, reason: str) -> None:
        self.line = line
        self.reason = reason
        super().__init__("line %d: %s" % (line, reason))


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"
    line: int = 0


@dataclass(frozen=True)
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    line: int = 0


@dataclass(frozen=True)
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: List[Tuple[str, int]] = field(default_factory=list)
    line: int = 0


def clip(text: str, limit: int = 40) -> str:
    """Shorten user text for use inside a message."""
    return text if len(text) <= limit else text[:limit] + "..."


def split_lines(text: str) -> List[str]:
    """Lines of ``text``: one leading BOM dropped, split on LF only, one CR trimmed."""
    if text.startswith("﻿"):
        text = text[1:]
    return [p[:-1] if p.endswith("\r") else p for p in text.split("\n")]


def _content_lines(text: str) -> Iterator[Tuple[int, str]]:
    for number, raw in enumerate(split_lines(text), 1):
        stripped = raw.strip(WS)
        if not stripped or stripped.startswith("#"):
            continue
        yield number, stripped


def parse_uint(text: str) -> Optional[int]:
    """``[0-9]+`` as an int, or None when it is not that (or absurdly long)."""
    if not _UINT_RE.fullmatch(text):
        return None
    digits = text.lstrip("0")
    if len(digits) > MAX_DIGITS:
        return None
    return int(digits) if digits else 0


def parse_signed(text: str) -> Optional[int]:
    """``[+-]?[0-9]+`` as an int, or None."""
    match = _SINT_RE.fullmatch(text)
    if not match:
        return None
    value = parse_uint(match.group(2))
    if value is None:
        return None
    return -value if match.group(1) == "-" else value


def parse_date(text: str) -> Optional[datetime.date]:
    """``YYYY-MM-DD`` naming a real date, or None."""
    if not _DATE_RE.fullmatch(text):
        return None
    try:
        return datetime.date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        return None


def normalise_sku(text: str) -> Optional[str]:
    """Upper-cased SKU when ``text`` has the SKU shape, else None."""
    return text.upper() if _SKU_RE.fullmatch(text) else None


def normalise_order_id(text: str) -> Optional[str]:
    """Upper-cased order id when ``text`` has the order shape, else None."""
    return text.upper() if _ORDER_RE.fullmatch(text) else None


def cents_to_decimal(cents: int) -> Decimal:
    """Exact two-decimal Decimal for an integer number of pennies."""
    digits = tuple(int(c) for c in str(abs(cents)).rjust(3, "0"))
    return Decimal((1 if cents < 0 else 0, digits, -2))


def parse_catalog(text: str) -> Dict[str, Product]:
    """Parse ``catalog.txt`` into ``{SKU: Product}`` in file order."""
    catalog = {}  # type: Dict[str, Product]
    for number, line in _content_lines(text):
        fields = [f.strip(WS) for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by '|', found %d" % len(fields))
        sku_text, name, price_text, reorder_text = fields[:4]
        sku = normalise_sku(sku_text)
        if sku is None:
            raise ParseError(number, "bad SKU '%s'" % clip(sku_text))
        if sku in catalog:
            raise ParseError(number, "duplicate SKU '%s'" % sku)
        if not name:
            raise ParseError(number, "empty name")
        price_match = _PRICE_RE.fullmatch(price_text)
        if not price_match:
            raise ParseError(number, "bad price '%s'" % clip(price_text))
        whole = parse_uint(price_match.group(1))
        if whole is None:
            raise ParseError(number, "price too large '%s'" % clip(price_text))
        cents = whole * 100 + int((price_match.group(2) or "0").ljust(2, "0"))
        if cents < 1:
            raise ParseError(number, "bad price '%s' (must be at least 0.01)" % clip(price_text))
        reorder = parse_uint(reorder_text)
        if reorder is None:
            raise ParseError(number, "bad reorder '%s'" % clip(reorder_text))
        tax = "standard"
        if len(fields) == 5:
            word = fields[4]
            if not (word.isascii() and word.lower() in TAX_RATES):
                raise ParseError(number, "bad tax '%s'" % clip(word))
            tax = word.lower()
        catalog[sku] = Product(sku, name, cents_to_decimal(cents), reorder, tax, number)
    return catalog


def check_stock(movements: List[Movement]) -> None:
    """Raise ParseError at the movement that first takes a SKU below zero.

    Movements count sorted by date, stably (the file order breaks ties).
    """
    balance = {}  # type: Dict[str, int]
    for move in sorted(movements, key=lambda m: m.date):
        total = balance.get(move.sku, 0) + move.quantity
        balance[move.sku] = total
        if total < 0:
            raise ParseError(move.line, "stock of %s would go below zero (%d)" % (move.sku, total))


def parse_movements(text: str, catalog: Dict[str, Product]) -> List[Movement]:
    """Parse ``movements.txt``; list is in file order. Stock never goes below zero."""
    movements = []  # type: List[Movement]
    for number, line in _content_lines(text):
        match = _MOVE_RE.fullmatch(line)
        if not match:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date_text, sku_text, qty_text, note = match.groups()
        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, "bad date '%s'" % clip(date_text))
        sku = normalise_sku(sku_text)
        if sku is None or sku not in catalog:
            raise ParseError(number, "unknown SKU '%s'" % clip(sku_text))
        quantity = parse_signed(qty_text)
        if quantity is None:
            raise ParseError(number, "bad quantity '%s'" % clip(qty_text))
        if quantity == 0:
            raise ParseError(number, "quantity may not be zero")
        movements.append(Movement(date, sku, quantity, (note or "").strip(WS), number))
    check_stock(movements)
    return movements


def parse_orders(text: str, catalog: Dict[str, Product]) -> List[Order]:
    """Parse ``orders.txt``; list is in file order."""
    orders = []  # type: List[Order]
    seen = set()
    for number, line in _content_lines(text):
        fields = re.split(r"[ \t]+", line)
        if len(fields) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES, found %d fields" % len(fields))
        id_text, date_text, customer, lines_text = fields
        order_id = normalise_order_id(id_text)
        if order_id is None:
            raise ParseError(number, "bad order number '%s'" % clip(id_text))
        if order_id in seen:
            raise ParseError(number, "duplicate order '%s'" % order_id)
        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, "bad date '%s'" % clip(date_text))
        lines = []  # type: List[Tuple[str, int]]
        used = set()
        for part in lines_text.split(","):
            match = _LINE_RE.fullmatch(part)
            if not match:
                raise ParseError(number, "bad order line '%s'" % clip(part))
            sku = match.group(1).upper()
            if sku not in catalog:
                raise ParseError(number, "unknown SKU '%s'" % sku)
            if sku in used:
                raise ParseError(number, "duplicate SKU '%s'" % sku)
            quantity = parse_uint(match.group(2))
            if quantity is None:
                raise ParseError(number, "bad quantity '%s'" % clip(match.group(2)))
            if quantity < 1:
                raise ParseError(number, "quantity must be at least 1")
            used.add(sku)
            lines.append((sku, quantity))
        seen.add(order_id)
        orders.append(Order(order_id, date, customer, lines, number))
    return orders
"""The ``stockroom`` command line."""

import csv
import datetime
import io
import json
import os
import sys
from typing import Callable, Dict, List, Optional, Tuple

from .orders import (
    owed,
    order_status,
    plan_fulfil,
    shipped_order,
    shipped_so_far,
)
from .parsing import (
    Movement,
    Order,
    ParseError,
    check_stock,
    clip,
    normalise_order_id,
    normalise_sku,
    parse_catalog,
    parse_date,
    parse_movements,
    parse_orders,
    parse_uint,
    WS,
)
from .pricing import Quote, price_order
from .shelves import history_rows, low_rows, stock_rows

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

USAGE = """\
usage: stockroom [--dir DIR] COMMAND [ARGS]

shelves:
  stockroom stock [--json]
  stockroom low [--json]
  stockroom history SKU [--json]
  stockroom receive DATE SKU QUANTITY [NOTE]
  stockroom ship DATE SKU QUANTITY [NOTE]
orders:
  stockroom quote ORDER [--json]
  stockroom fulfil ORDER DATE
  stockroom invoice ORDER [--json]
  stockroom report [--format text|csv|json]

--dir DIR   folder holding catalog.txt, movements.txt and orders.txt
            (default: the current folder); it may appear anywhere.
-h, --help  show this help.
"""

#: command -> (files it reads, positionals allowed (min, max), takes --json)
COMMANDS = {
    "stock": ((CATALOG, MOVEMENTS), (0, 0), True),
    "low": ((CATALOG, MOVEMENTS), (0, 0), True),
    "history": ((CATALOG, MOVEMENTS), (1, 1), True),
    "receive": ((CATALOG, MOVEMENTS), (3, 4), False),
    "ship": ((CATALOG, MOVEMENTS), (3, 4), False),
    "quote": ((CATALOG, ORDERS), (1, 1), True),
    "fulfil": ((CATALOG, MOVEMENTS, ORDERS), (2, 2), False),
    "invoice": ((CATALOG, MOVEMENTS, ORDERS), (1, 1), True),
    "report": ((CATALOG, MOVEMENTS, ORDERS), (0, 0), False),
}
#: Commands whose arguments (other than --dir) are all taken as typed.
AS_TYPED = ("receive", "ship", "fulfil")
FORMATS = ("text", "csv", "json")
REPORT_COLUMNS = ("order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced")


class CliError(Exception):
    """Something to report on stderr and exit with ``code``."""

    def __init__(self, code: int, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


class Args:
    def __init__(self) -> None:
        self.command = ""
        self.dir = None  # type: Optional[str]
        self.json = False
        self.format = "text"
        self.format_given = False
        self.positional = []  # type: List[str]


# ---------------------------------------------------------------- command line


def _wants_help(argv: List[str]) -> bool:
    command = None
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            i += 2
            continue
        if arg.startswith("--dir="):
            i += 1
            continue
        if arg in ("-h", "--help"):
            return True
        if command is None and not (arg.startswith("-") and arg != "-"):
            command = arg
            if command in AS_TYPED:
                return False
        i += 1
    return False


def parse_args(argv: List[str]) -> Args:
    args = Args()
    command_seen = False
    i = 0
    while i < len(argv):
        arg = argv[i]
        i += 1
        if arg == "--dir" or arg.startswith("--dir="):
            if arg == "--dir":
                if i >= len(argv):
                    raise CliError(2, "--dir needs a value")
                value = argv[i]
                i += 1
            else:
                value = arg[len("--dir="):]
            if not value:
                raise CliError(2, "--dir needs a value")
            args.dir = value
            continue
        as_typed = command_seen and args.command in AS_TYPED
        if as_typed or arg == "-" or not arg.startswith("-"):
            if not command_seen:
                if arg not in COMMANDS:
                    raise CliError(2, "unknown command '%s'" % clip(arg))
                args.command = arg
                command_seen = True
            else:
                args.positional.append(arg)
            continue
        if arg == "--json":
            args.json = True
        elif arg == "--format" or arg.startswith("--format="):
            if arg == "--format":
                if i >= len(argv):
                    raise CliError(2, "--format needs a value")
                value = argv[i]
                i += 1
            else:
                value = arg[len("--format="):]
            if value not in FORMATS:
                raise CliError(2, "bad --format value '%s' (use text, csv or json)" % clip(value))
            args.format = value
            args.format_given = True
        else:
            raise CliError(2, "unknown option '%s'" % clip(arg))
    if not command_seen:
        raise CliError(2, "no command given (try --help)")
    low, high = COMMANDS[args.command][1]
    if not low <= len(args.positional) <= high:
        raise CliError(2, "wrong number of arguments for '%s' (try --help)" % args.command)
    if args.json and not COMMANDS[args.command][2]:
        raise CliError(2, "unknown option '--json'")
    if args.format_given and args.command != "report":
        raise CliError(2, "unknown option '--format'")
    if args.command in AS_TYPED:
        for text in args.positional:
            try:
                text.encode("utf-8")
            except UnicodeEncodeError:
                raise CliError(2, "argument is not valid UTF-8")
        date_text = args.positional[0] if args.command != "fulfil" else args.positional[1]
        if parse_date(date_text) is None:
            raise CliError(2, "bad date '%s' (use YYYY-MM-DD)" % clip(date_text))
    return args


# ----------------------------------------------------------------------- files


class Files:
    """The raw text of each file a command needs."""

    def __init__(self, directory: Optional[str]) -> None:
        self.directory = directory
        self.text = {}  # type: Dict[str, str]
        self.raw = {}  # type: Dict[str, bytes]

    def path(self, name: str) -> str:
        return name if self.directory is None else os.path.join(self.directory, name)

    def read(self, name: str, required: bool) -> None:
        path = self.path(name)
        try:
            with open(path, "rb") as handle:
                data = handle.read()
        except FileNotFoundError:
            if required:
                raise CliError(2, "cannot read %s: no such file" % path)
            data = b""
        except (OSError, ValueError) as exc:
            reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else str(exc)
            raise CliError(2, "cannot read %s: %s" % (path, reason))
        try:
            text = data.decode("utf-8")
        except UnicodeDecodeError:
            raise CliError(2, "%s is not valid UTF-8" % path)
        self.raw[name] = data
        self.text[name] = text


def _parse_files(files: Files, names: Tuple[str, ...]):
    """Parse the files a command reads, in order; returns (catalog, movements, orders)."""
    catalog = {}
    movements = []  # type: List[Movement]
    orders = []  # type: List[Order]
    for name in names:
        try:
            if name == CATALOG:
                catalog = parse_catalog(files.text[name])
            elif name == MOVEMENTS:
                movements = parse_movements(files.text[name], catalog)
            else:
                orders = parse_orders(files.text[name], catalog)
        except ParseError as exc:
            raise CliError(1, "%s %s" % (files.path(name), exc))
    return catalog, movements, orders


# -------------------------------------------------------------------- rendering


def _json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def _lines(rows: List[str]) -> str:
    return "".join(row + "\n" for row in rows)


def _quote_text(header: str, quote: Quote) -> str:
    rows = [header]
    for line in quote.lines:
        rows.append("%s %d %s %s %s %s" % (line.sku, line.quantity, line.unit, line.gross, line.discount, line.net))
    rows.append("subtotal %s" % quote.subtotal)
    rows.append("order discount %s" % quote.order_discount)
    rows.append("tax %s" % quote.tax)
    rows.append("total %s" % quote.total)
    return _lines(rows)


def _quote_json(order: Order, quote: Quote) -> str:
    return _json(
        {
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": line.sku,
                    "quantity": line.quantity,
                    "unit": str(line.unit),
                    "gross": str(line.gross),
                    "discount": str(line.discount),
                    "net": str(line.net),
                }
                for line in quote.lines
            ],
            "subtotal": str(quote.subtotal),
            "order_discount": str(quote.order_discount),
            "tax": str(quote.tax),
            "total": str(quote.total),
        }
    )


def _movement_line(date: datetime.date, sku: str, quantity: int, note: str) -> str:
    text = "%s %s %+d" % (date.isoformat(), sku, quantity)
    return text + " " + note if note else text


# --------------------------------------------------------------------- commands


def _find_order(orders: List[Order], text: str) -> Order:
    order_id = normalise_order_id(text)
    for order in orders:
        if order.id == order_id:
            return order
    raise CliError(1, "unknown order '%s'" % clip(text))


def _cmd_stock(args, files, catalog, movements, orders) -> str:
    rows = stock_rows(catalog, movements)
    if args.json:
        return _json([{"sku": r.sku, "name": r.name, "onhand": r.onhand, "status": r.status} for r in rows])
    return _lines(["%s %d %s %s" % (r.sku, r.onhand, r.status, r.name) for r in rows])


def _cmd_low(args, files, catalog, movements, orders) -> str:
    rows = low_rows(catalog, movements)
    if args.json:
        return _json([{"sku": r.sku, "onhand": r.onhand, "reorder": r.reorder, "buy": r.buy} for r in rows])
    return _lines(["%s %d %d %d" % (r.sku, r.onhand, r.reorder, r.buy) for r in rows])


def _cmd_history(args, files, catalog, movements, orders) -> str:
    text = args.positional[0]
    sku = normalise_sku(text)
    if sku is None or sku not in catalog:
        raise CliError(1, "unknown SKU '%s'" % clip(text))
    rows = history_rows(sku, movements)
    if args.json:
        return _json(
            [{"date": r.date.isoformat(), "delta": "%+d" % r.delta, "balance": r.balance, "note": r.note} for r in rows]
        )
    out = []
    for r in rows:
        line = "%s %+d %d" % (r.date.isoformat(), r.delta, r.balance)
        out.append(line + " " + r.note if r.note else line)
    return _lines(out)


def _append(files: Files, new_lines: List[str]) -> None:
    """Append lines to movements.txt: a missing final newline first, file created if absent."""
    existing = files.raw.get(MOVEMENTS, b"")
    payload = b"" if not existing or existing.endswith(b"\n") else b"\n"
    payload += "".join(line + "\n" for line in new_lines).encode("utf-8")
    path = files.path(MOVEMENTS)
    try:
        with open(path, "ab") as handle:
            handle.write(payload)
    except (OSError, ValueError) as exc:
        reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else str(exc)
        raise CliError(2, "cannot write %s: %s" % (path, reason))


def _next_line_number(raw: bytes) -> int:
    """Line number the next appended line will have in the file."""
    unterminated = 1 if raw and not raw.endswith(b"\n") else 0
    return raw.count(b"\n") + unterminated + 1


def _cmd_move(args, files, catalog, movements, orders) -> str:
    date_text, sku_text, qty_text = args.positional[:3]
    note = (args.positional[3] if len(args.positional) == 4 else "").strip(WS)
    date = parse_date(date_text)
    sku = normalise_sku(sku_text)
    if sku is None or sku not in catalog:
        raise CliError(1, "unknown SKU '%s'" % clip(sku_text))
    quantity = parse_uint(qty_text)
    if quantity is None or quantity < 1:
        raise CliError(1, "bad quantity '%s' (must be a whole number of 1 or more)" % clip(qty_text))
    if "\n" in note or "\r" in note:
        raise CliError(1, "a note may not contain a line break")
    delta = quantity if args.command == "receive" else -quantity
    line_no = _next_line_number(files.raw[MOVEMENTS])
    candidate = Movement(date, sku, delta, note, line_no)
    try:
        check_stock(movements + [candidate])
    except ParseError as exc:
        if exc.line == line_no:
            raise CliError(1, "refused: %s" % exc.reason)
        raise CliError(1, "refused: %s %s" % (files.path(MOVEMENTS), exc))
    text = _movement_line(date, sku, delta, note)
    _append(files, [text])
    return text + "\n"


def _cmd_quote(args, files, catalog, movements, orders) -> str:
    order = _find_order(orders, args.positional[0])
    quote = price_order(order, catalog)
    if args.json:
        return _quote_json(order, quote)
    return _quote_text("%s %s %s" % (order.id, order.date.isoformat(), order.customer), quote)


def _cmd_fulfil(args, files, catalog, movements, orders) -> str:
    order = _find_order(orders, args.positional[0])
    date = parse_date(args.positional[1])
    if date < order.date:
        raise CliError(1, "refused: %s is before the order date %s" % (date.isoformat(), order.date.isoformat()))
    before = shipped_so_far(order, movements)
    plan = plan_fulfil(order, date, movements)
    new_lines = [
        _movement_line(date, sku, -plan[sku], "order " + order.id) for sku, _ in order.lines if plan[sku] > 0
    ]
    if new_lines:
        _append(files, new_lines)
    after = {sku: before[sku] + plan[sku] for sku, _ in order.lines}
    left = owed(order, after)
    out = ["%s shipped %d backordered %d" % (sku, plan[sku], left[sku]) for sku, _ in order.lines]
    out.append("status " + order_status(order, after))
    return _lines(out)


def _cmd_invoice(args, files, catalog, movements, orders) -> str:
    order = _find_order(orders, args.positional[0])
    shipped = shipped_so_far(order, movements)
    invoiced = shipped_order(order, shipped)
    if not invoiced.lines:
        raise CliError(1, "nothing shipped yet for %s" % order.id)
    quote = price_order(invoiced, catalog)
    if args.json:
        return _quote_json(order, quote)
    return _quote_text("invoice %s %s %s" % (order.id, order.date.isoformat(), order.customer), quote)


def _order_sort_key(order: Order):
    digits = order.id[3:].lstrip("0")
    return (order.date, len(digits), digits, order.id)


def _cmd_report(args, files, catalog, movements, orders) -> str:
    rows = []
    for order in sorted(orders, key=_order_sort_key):
        shipped = shipped_so_far(order, movements)
        invoiced = shipped_order(order, shipped)
        quoted = price_order(order, catalog).total
        billed = price_order(invoiced, catalog).total
        rows.append(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "status": order_status(order, shipped),
                "ordered": sum(q for _, q in order.lines),
                "shipped": sum(shipped.values()),
                "quoted": str(quoted),
                "invoiced": str(billed),
            }
        )
    if args.format == "json":
        return _json(rows)
    if args.format == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(REPORT_COLUMNS)
        for row in rows:
            writer.writerow([row[c] for c in REPORT_COLUMNS])
        return buffer.getvalue()
    return _lines(
        [
            "%s %s %s %s %d/%d %s %s"
            % (r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
            for r in rows
        ]
    )


HANDLERS = {
    "stock": _cmd_stock,
    "low": _cmd_low,
    "history": _cmd_history,
    "receive": _cmd_move,
    "ship": _cmd_move,
    "quote": _cmd_quote,
    "fulfil": _cmd_fulfil,
    "invoice": _cmd_invoice,
    "report": _cmd_report,
}  # type: Dict[str, Callable]


# ------------------------------------------------------------------------- main


def _emit(stream_name: str, text: str) -> None:
    stream = getattr(sys, stream_name)
    data = text.encode("utf-8", "backslashreplace")
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        buffer.write(data)
        buffer.flush()
    else:
        stream.write(data.decode("utf-8"))
        stream.flush()


def _silence_stdout() -> None:
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv: Optional[List[str]] = None) -> int:
    """Run the command line; returns the exit status."""
    argv = list(sys.argv[1:] if argv is None else argv)
    output = ""
    try:
        if _wants_help(argv):
            output = USAGE
        else:
            args = parse_args(argv)
            names = COMMANDS[args.command][0]
            files = Files(args.dir)
            for name in names:
                files.read(name, required=(name == CATALOG))
            catalog, movements, orders = _parse_files(files, names)
            output = HANDLERS[args.command](args, files, catalog, movements, orders)
    except CliError as exc:
        try:
            _emit("stderr", "stockroom: %s\n" % exc.message)
        except (OSError, ValueError):
            pass
        return exc.code
    try:
        _emit("stdout", output)
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except (OSError, ValueError) as exc:
        _silence_stdout()
        try:
            _emit("stderr", "stockroom: cannot write output: %s\n" % exc)
        except (OSError, ValueError):
            pass
        return 2
    return 0

